window.NPC_CHUNK_234 = [{"name":"Disciple Of Dark Water","cr":2,"xp":600,"race":"Lizardfolk","age_category":"Adult","classes":[{"class":"cleric of Kelizandri","level":2}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["reptilian"],"init":0,"ac":18,"ac_touch":10,"ac_flat_footed":18,"ac_mods":"+3 armor, +5 natural","hp":20,"hd":"4d8+2","hd_value":4,"fort":6,"ref":2,"will":4,"speed":[{"type":"land","speed":30},{"type":"swim","speed":15}],"melee":"mwk trident +6 (1d8+4), bite +0 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"4/day, DC 12, 1d6"},{"type":"destructive smite","details":"+1, 4/day"}],"spell_like_abilities_caster_level":2,"spell_like_abilities_concentration":3,"spell_like_abilities":[{"frequency":"4/day","spells":[{"spell":"icicle","details":"1d6+1 cold"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":2,"spellsprepared_concentration":3,"spellsprepared":[{"spell_level":1,"spell_slots":4,"spells":[{"spell":"cure light wounds"},{"spell":"endure elements"},{"spell":"entropic shield"},{"spell":"true strike","type":"domain"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"create water"},{"spell":"light"},{"spell":"resistance"}]}],"spelldomains":"Destruction, Water","strength":17,"dexterity":10,"constitution":10,"intelligence":12,"wisdom":13,"charisma":12,"baseatk":2,"cmb":5,"cmd":15,"feats":[{"feat":"Lightning Reflexes"},{"feat":"Power Attack"}],"skills":[{"skill":"Acrobatics","value":4},{"skill":"Climb","value":7},{"skill":"Handle Animal","value":7},{"skill":"Knowledge (religion)","value":5},{"skill":"Sense Motive","value":7},{"skill":"Spellcraft","value":7},{"skill":"Swim","value":12}],"languages":["Draconic","Polyglot"],"sq":["hold breath"],"gear":"+1 leather armor, mwk trident, silver unholy symbol of Kelizandri (worth 25 gp), scroll of spiritual weapon","before_combat":"Each morning the disciples cast endure elements on themselves to navigate the dungeon's extreme climates. If they hear combat nearby, they cast entropic shield.","during_combat":"Daruthek's disciples attack with destructive smite and tridents or hurl icicles at distant opponents. They use little strategy, pausing to heal themselves only if reduced to fewer than half their hit points.","morale":"The disciples fight to the death.","source":"Ire Of The Storm, Pathfinder RPG Bestiary 195"},{"name":"Uurgu","cr":4,"xp":1200,"race":"lizardfolk","gender":"Female","age_category":"Adult","classes":[{"class":"inquisitor of Hshurha","level":4}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["reptilian"],"init":4,"ac":20,"ac_touch":12,"ac_flat_footed":18,"ac_mods":"+3 armor, +2 Dex, +5 natural","hp":37,"hd":"6d8+10","hd_value":6,"fort":9,"ref":4,"will":7,"dr":"1/magic","speed":[{"type":"land","speed":30},{"type":"swim","speed":15}],"melee":"+1 quarterstaff +10 (1d6+6), bite +3 (1d4+2) or +1 quarterstaff +8 (1d6+5), +1 quarterstaff +8 (1d6+5), bite +3 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"judgment","details":"2/day"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect alignment"}]},{"frequency":"5/day","spells":[{"spell":"touch of evil","details":"2 rounds"}]}],"spellsknown_caster":"inquisitor","spellsknown_caster_level":4,"spellsknown_concentration":6,"spellsknown":[{"spell_level":2,"spell_slots":2,"spells":[{"spell":"death knell"},{"spell":"silence"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"alarm"},{"spell":"cause fear"},{"spell":"divine favor"},{"spell":"magic weapon"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"read magic"},{"spell":"resistance"},{"spell":"virtue"}]}],"spelldomains":"Evil","strength":16,"dexterity":15,"constitution":12,"intelligence":10,"wisdom":14,"charisma":8,"baseatk":4,"cmb":8,"cmd":19,"feats":[{"feat":"Double Slice"},{"feat":"Precise Strike"},{"feat":"Two-weapon Fighting"},{"feat":"Weapon Focus (quarterstaff)"}],"skills":[{"skill":"Acrobatics","value":6},{"skill":"Heal","value":9},{"skill":"Intimidate","value":6},{"skill":"Knowledge (planes)","value":7},{"skill":"Knowledge (religion)","value":7},{"skill":"Perception","value":9},{"skill":"Sense Motive","value":11},{"skill":"Stealth","value":9},{"skill":"Survival","value":7},{"skill":"Swim","value":11}],"languages":["Polyglot"],"sq":["hold breath","monster lore +2","solo tactics","stern gaze +2","track +2"],"gear":"mwk studded leather, mwk quarterstaff, cloak of resistance +1, manacles, gold holy symbol of Hshurha (worth 60 gp), potion of cure moderate wounds, potion of darkvision, salve of slipperiness","before_combat":"Uurgu casts alarm on area N16 each day, and if alerted to intruders, casts divine favor on herself and magic weapon on her staff.","during_combat":"Uurgu offers intruders one chance to surrender (for later sacrifice to the elemental lord she worships) before declaring her judgment of resiliency and launching into combat. She targets enemy divine casters with silence, then attacks with her staff. If one of her cultists falls, she slays him with death knell.","morale":"Uurgu fights to the death.","base_statistics":"Without divine favor and magic weapon cast, Uurgu's statistics are Melee quarterstaff +9 (1d6+4), bite +3 (1d4+1), or quarterstaff +7 (1d6+3), quarterstaff +7 (1d6+3), bite +2 (1d4+1).","source":"Ire Of The Storm, Pathfinder RPG Bestiary 195, Pathfinder RPG Advanced Player's Guide 38"},{"name":"Daruthek","cr":6,"xp":2400,"race":"lizardfolk","gender":"Male","age_category":"Adult","classes":[{"class":"oracle","level":5}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["reptilian"],"templates_applied":"air-infused","init":1,"senses":["blindsight 30 ft."],"ac":25,"ac_touch":13,"ac_flat_footed":24,"ac_mods":"+7 armor, +2 deflection, +1 Dex, +5 natural","hp":50,"hd":"7d8+19","hd_value":7,"fort":7,"ref":6,"will":9,"immunities":["fatigue"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"},{"type":"land","speed":15,"special":"20 ft. without armor"},{"type":"swim","speed":15}],"melee":"+1 spear +7 (1d8+4/x3), bite +1 (1d4+1)","ranged":"light crossbow +5 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"gaseous form"}]}],"spellsknown_caster":"oracle","spellsknown_caster_level":5,"spellsknown_concentration":9,"spellsknown":[{"spell_level":2,"spell_slots":5,"spells":[{"spell":"cure moderate wounds"},{"spell":"gust of wind"},{"spell":"resist energy"},{"spell":"sound burst"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"alter winds"},{"spell":"cause fear"},{"spell":"cure light wounds"},{"spell":"inflict light wounds"},{"spell":"obscuring mist"},{"spell":"protection from good"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"create water"},{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"guidance"},{"spell":"read magic"}]}],"mystery":"wind","strength":14,"dexterity":12,"constitution":13,"intelligence":10,"wisdom":12,"charisma":18,"baseatk":4,"cmb":6,"cmd":19,"feats":[{"feat":"Flyby Attack"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes","type":"bonus"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":2,"special":"-8 when jumping"},{"skill":"Diplomacy","value":12},{"skill":"Fly","value":14},{"skill":"Knowledge (planes)","value":7},{"skill":"Knowledge (religion)","value":7},{"skill":"Linguistics","value":1},{"skill":"Spellcraft","value":7},{"skill":"Stealth","value":2},{"skill":"Swim","value":7}],"languages":["Auran","Polyglot"],"sq":["hold breath","oracle's curse (lame)","revelations (invisibility, lightning breath)"],"special_abilities":[{"type":"Air Mastery","kind":"Ex","details":"Airborne creatures take a -1 penalty on attack rolls and damage rolls against Daruthek."},{"type":"Elemental Body","kind":"Ex","details":"Each time Daruthek is subject to bleed damage, precision damage, poison, paralysis, sleep, or a stunning effect, there is a 25% chance that the effect or additional damage is negated."},{"type":"Wind Blast","kind":"Su","details":"Once every 1d4 rounds, Daruthek can breathe a 60-foot cone of wind. Every creature within this area that isn't flying must succeed at a DC 14 Acrobatics or Strength check or fall prone. A flying creature that fails is instead blown away from Daruthek, moving a distance equal to 5 ft. per point by which it failed the check. If the creature encounters a large object during this movement, it takes 1d6 points of damage per 5 ft. the object prevented it from moving. The save DC is Constitution-based."}],"gear":"+1 spell-storing breastplate, +1 spear, light crossbow with 20 bolts, potion of bull's strength (2), potion of cure moderate wounds (2)","before_combat":"Daruthek casts protection from good and drinks a potion of bull's strength once the storm seeds are destroyed and the storm engine's barrier falls.","during_combat":"Daruthek uses his lightning breath early to target opponents before his cultists close to melee, then relies on sound burst and flyby attacks with his spear to harry small groups of enemies. If his cultists die, he uses obscuring mist to blind opponents, relying on his blindsight to target them with attacks. The oracle keeps a cause fear spell in his +1 spell-storing breastplate, and targets the first creature who strikes him in melee.","morale":"Daruthek and his minions fight to the death.","base_statistics":"Without a potion of bull's strength or casting protection from good, Daruthek statistics are AC 23 (touch 11, flat-footed 22); Fort +5, Ref +4, Will +7, +1 spear +5 (1d8+1/x3), bite -1 (1d4); Str 10; CMB +4, CMD 15; Skills Swim +5.","source":"Ire Of The Storm, Advanced Bestiary 139, Pathfinder RPG Bestiary 195, Pathfinder RPG Advanced Player's Guide 42"},{"name":"Wrong One","cr":5,"xp":1600,"race":"myceloid","age_category":"Adult","alignment":"NE","size":"Medium","type":"aberration","sub_types":["augmented plant"],"templates_applied":"flesh","init":6,"senses":["darkvision 60 ft.","low-light vision","scent","tremorsense 20 ft."],"ac":18,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+2 Dex, +6 natural","hp":52,"hd":"5d8+30","hd_value":5,"hp_mods":"fast healing 2","fort":9,"ref":3,"will":4,"dr":"5/slashing","immunities":["purple pox"],"resists":["cold 10","fire 10","sonic 10"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +8 (1d6+5 plus bleed)","space":"5 ft.","reach":"10 ft.","special_attacks":[{"type":"bleed","details":"1d4"},{"type":"long limbs"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"remorseful aspect"}]}],"strength":21,"dexterity":15,"constitution":20,"intelligence":9,"wisdom":12,"charisma":10,"baseatk":3,"cmb":8,"cmd":20,"feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":6},{"skill":"Sense Motive","value":6},{"skill":"Stealth","value":6},{"skill":"Survival","value":9}],"languages":["Undercommon; telepathy 60 ft. (myceloid and purple pox sufferers only)"],"special_abilities":[{"type":"Long Limbs","kind":"Ex","details":"As a result of its faceless stalker ancestry, the Wrong One's arms are lengthier than that of normal myceloids, giving it reach of 10 feet."},{"type":"Remorseful Aspect","kind":"Sp","details":"The Wrong One can adjust its skin to crudely resemble the appearance of another creature it can see, the sight of which fills the target with profound disgust and remorse. This spell-like ability functions as terrible remorse. Creatures currently infected with purple pox take a -2 penalty on saving throws against this ability."}],"during_combat":"The Wrong One uses its remorseful aspect spell-like ability against intruders, preferring victims already suffering from purple pox. When an opponent gets within its reach, the Wrong One attacks with its claws.","morale":"The Wrong One fights to the death unless Mam or Pap commands it to stop fighting.","source":"AP 104, Advanced Bestiary 148, Pathfinder RPG Bestiary 3 196","unique_monster":1},{"name":"Eloko","cr":3,"xp":800,"race":"Spriggan","age_category":"Adult","alignment":"CE","size":"Small","type":"humanoid","sub_types":["gnome"],"init":4,"senses":["low-light vision"],"ac":17,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+2 armor, +4 Dex, +1 size","hp":22,"hd":"4d8+4","hd_value":4,"fort":5,"ref":5,"will":1,"speed":[{"type":"land","speed":20}],"melee":"mwk halberd +5 (1d8-1/3)","ranged":"dagger +8 (1d3-1/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"flare"},{"spell":"scare"},{"spell":"shatter"}]}],"strength":9,"dexterity":19,"constitution":12,"intelligence":10,"wisdom":10,"charisma":9,"baseatk":3,"cmb":1,"cmd":15,"feats":[{"feat":"Combat Reflexes"},{"feat":"Weapon Focus (halberd)"}],"skills":[{"skill":"Climb","value":1},{"skill":"Disable Device","value":11},{"skill":"Perception","value":7},{"skill":"Sleight of Hand","value":11},{"skill":"Stealth","value":15}],"languages":["Aklo","Gnome"],"sq":["size alteration","spriggan magic","spriggan skills"],"special_abilities":[{"type":"Size Alteration","kind":"Su","details":"At will, as a standard action, a spriggan can change its size between Small and Large. Weapons, armor, and other objects on the spriggan's person grow proportionally when it changes size (objects revert to normal size 1 round after a spriggan releases them). When a spriggan becomes Large, its speed increases to 30 feet, and it gains +12 Strength, -2 Dexterity, +6 Constitution, and a -2 size penalty to its AC. While Large, a spriggan cannot use its sneak attack or its racial spell-like abilities (although if it possesses either from class levels or templates, it retains their use in both sizes)."},{"type":"Spriggan Magic","kind":"Ex","details":"A spriggan gains a +1 racial bonus on concentration checks and save DCs for all of its racial spell-like abilities."},{"type":"Spriggan Skills","kind":"Ex","details":"Climb, Disable Device, Perception, Sleight of Hand, and Stealth are class skills for spriggans."}],"gear":"leather armor, daggers (4), masterwork halberd, Eloko bell (one only)","during_combat":"Eloko step from the bushes, startling targets and immediately growing to a terrifying size. They attack mercilessly, but break from combat to eat victims as soon as one falls unconscious.","morale":"Ultimately, these creatures are cowardly and flee if reduced to fewer than 5 hit points.","source":"AP 38, Tome of Horrors Revised 326"},{"name":"Glorious Reclamation Knight Inheritor","cr":8,"xp":4800,"race":"human","age_category":"Adult","classes":[{"class":"paladin","level":9}],"alignment":"LG","size":"Medium","type":"humanoid","sub_types":["human"],"init":-1,"auras":["courage (10 ft.)","resolve (10 ft.)"],"ac":23,"ac_touch":9,"ac_flat_footed":23,"ac_mods":"+9 armor, -1 Dex, +5 shield","hp":90,"hd":"9d10+36","hd_value":9,"fort":11,"ref":5,"will":11,"immunities":["charm","disease","fear"],"speed":[{"type":"land","speed":20,"special":"30 ft. without armor"}],"melee":"+1 longsword +15 (1d8+5/17-20)","ranged":"mwk composite longbow +9 (1d8+2/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel positive energy","details":"3/day, DC 17, 5d6"},{"type":"smite evil","details":"3/day, +3 attack and AC, +9 damage"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect evil"}]}],"spellsprepared_caster":"paladin","spellsprepared_caster_level":6,"spellsprepared_concentration":9,"spellsprepared":[{"spell_level":2,"spell_slots":2,"spells":[{"spell":"bull's strength"},{"spell":"resist energy"}]},{"spell_level":1,"spell_slots":3,"spells":[{"spell":"cure light wounds"},{"spell":"divine favor"},{"spell":"protection from evil"}]}],"strength":18,"dexterity":8,"constitution":14,"intelligence":10,"wisdom":14,"charisma":16,"baseatk":9,"cmb":13,"cmd":22,"feats":[{"feat":"Improved Critical (longsword)"},{"feat":"Power Attack"},{"feat":"Selective Channeling"},{"feat":"Shield Focus"},{"feat":"Toughness"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Acrobatics","value":-8,"special":"-4 to jump"},{"skill":"Diplomacy","value":15},{"skill":"Perception","value":11},{"skill":"Sense Motive","value":14}],"languages":["Common"],"sq":["divine bond (weapon +2, 2/day)","lay on hands 7/day (4d6)","mercies (diseased, fatigued, poisoned)"],"gear":"+1 half-plate, +2 heavy steel shield, +1 longsword, mwk composite longbow (+2 Str) and 20 arrows, skeleton key for most doors in Citadel Dinyar, 15 gp, potion of cure moderate wounds (4)","before_combat":"A Glorious Reclamation knight inheritor casts bull's strength on herself before combat.","during_combat":"A knight inheritor usually lets the enemy come to her, taking the first round of combat to cast divine favor and the next to cast protection from evil or resist energy (as best suits the opposition she faces).","morale":"A knight inheritor fights to the death.","source":"AP 107"},{"name":"Malebolgian Cerberi","cr":12,"xp":19200,"race":"cerberi","age_category":"Adult","alignment":"LE","size":"Large","type":"outsider","sub_types":["evil","extraplanar","lawful"],"templates_applied":"advanced","init":5,"senses":["darkvision 60 ft.","soul scent"],"ac":25,"ac_touch":10,"ac_flat_footed":24,"ac_mods":"+7 armor, +1 Dex, +8 natural, -1 size","hp":208,"hd":"14d10+98","hd_value":14,"fort":16,"ref":10,"will":6,"speed":[{"type":"land","speed":40}],"melee":"3 bites +20 (2d6+7 plus cerberus's jaws)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"rend","details":"2 bites, 1d8+10 or 3 bites, 1d8+14"}],"strength":24,"dexterity":12,"constitution":24,"intelligence":6,"wisdom":15,"charisma":9,"baseatk":14,"cmb":22,"cmd":33,"cmd_special":"37 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Improved Natural Attack (bite)"},{"feat":"Light Armor Proficiency"},{"feat":"Power Attack"},{"feat":"Stand Still"}],"skills":[{"skill":"Acrobatics","value":18},{"skill":"Perception","value":23},{"skill":"Sense Motive","value":4},{"skill":"Stealth","value":14},{"skill":"Survival","value":16,"special":"+4 to track vs. undead"}],"languages":["Infernal (can't speak)"],"gear":"+4 studded leather barding","during_combat":"The Malebolgian cerberi attacks the closest foe each round, abandoning this tactic only if someone attempts to move through the secret door to the east- anyone attempting to go deeper into the dungeon becomes its primary target. Tormented from beyond its reach, the cerberi can attempt to break the chain with a Strength check each round.","morale":"The cerberi fights to the death.","source":"AP 107, Pathfinder RPG Bestiary 3 51"},{"name":"Caraniel Glintleaf","cr":10,"xp":9600,"race":"elf","gender":"Female","age_category":"Adult","classes":[{"class":"enchanter","level":11}],"alignment":"NG","size":"Medium","type":"humanoid","sub_types":["elf"],"init":4,"senses":["low-light vision"],"auras":["despair (30 ft., 11 rounds/day)"],"ac":27,"ac_touch":17,"ac_flat_footed":22,"ac_mods":"+4 armor, +2 deflection, +4 Dex, +1 dodge, +2 natural, +4 shield","hp":63,"hd":"11d6+22","hd_value":11,"fort":3,"ref":7,"will":7,"save_mods":"+2 vs. enchantments","immunities":["sleep"],"speed":[{"type":"land","speed":30}],"melee":"dagger +4 (1d4-1/19-20)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"7/day","spells":[{"spell":"dazing touch"}]}],"spellsprepared_caster":"enchanter","spellsprepared_caster_level":11,"spellsprepared_concentration":15,"spellsprepared":[{"spell_level":6,"spell_slots":2,"spells":[{"spell":"greater dispel magic"},{"spell":"mass suggestion"}]},{"spell_level":5,"spell_slots":3,"spells":[{"spell":"feeblemind"},{"spell":"mind fog"},{"spell":"teleport"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"charm monster"},{"spell":"confusion","count":2},{"spell":"dimension door"},{"spell":"greater invisibility"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"deep slumber"},{"spell":"dispel magic"},{"spell":"fly"},{"spell":"haste"},{"spell":"suggestion"},{"spell":"summon monster III"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"enthrall"},{"spell":"glitterdust"},{"spell":"hideous laughter","count":2},{"spell":"mirror image"},{"spell":"web"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"charm person"},{"spell":"color spray"},{"spell":"grease","count":2},{"spell":"shield"},{"spell":"unseen servant"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"mage hand"},{"spell":"message"},{"spell":"prestidigitation"}]}],"prohibited_schools":"evocation, necromancy","strength":8,"dexterity":18,"constitution":10,"intelligence":19,"wisdom":10,"charisma":13,"baseatk":5,"cmb":4,"cmd":21,"feats":[{"feat":"Alertness"},{"feat":"Combat Casting"},{"feat":"Craft Wand"},{"feat":"Craft Wondrous Item"},{"feat":"Dodge"},{"feat":"Greater Spell Focus (enchantment)"},{"feat":"Scribe Scroll"},{"feat":"Spell Focus (enchantment)"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":5},{"skill":"Diplomacy","value":5},{"skill":"Fly","value":18},{"skill":"Intimidate","value":5},{"skill":"Knowledge (arcana)","value":18},{"skill":"Perception","value":17},{"skill":"Sense Motive","value":15},{"skill":"Sleight of Hand","value":15},{"skill":"Spellcraft","value":18}],"languages":["Common","Celestial","Draconic","Elven","Gnome","Sylvan"],"sq":["arcane bond (amulet of natural armor +2)","elven magic","enchanting smile"],"gear":"dagger, amulet of natural armor +2, belt of incredible dexterity +2, ring of protection +2, 24 pp, 43 gp, wand of hold person (15 charges), wand of mage armor (CL 11th, 8 charges)","before_combat":"Caraniel casts mage armor at the start of her shift, and shield as soon as she suspects combat is about to occur.","during_combat":"Caraniel opens combat by casting greater invisibility on herself, followed by shield if that spell isn't already active. She casts haste on allies early in combat long as they still stand to benefit. She then casts mind fog, followed by her more powerful mind-affecting spells. When she's a few rounds away from running out the duration of greater invisibility (or as soon as she can after this effect is removed early), she casts mirror image.","morale":"Caraniel fights until reduced below 10 hit points, at which point she attempts to teleport to her home in Kyonin. She remains there for a day until, racked with guilt at abandoning her post, she pays for a scroll of sending to contact Knight Commander Phand to offer additional aid free of charge; in this case, the PCs may well encounter her again fighting at his side, in which event she fights to the death.","source":"AP 107"},{"name":"Resarc Ountor","cr":9,"xp":6400,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"cleric of Asmodeus","level":2},{"class":"fighter","level":4},{"class":"Hellknight","level":4}],"alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human"],"init":-1,"ac":9,"ac_touch":9,"ac_flat_footed":9,"ac_mods":"-1 Dex","hp":91,"hd":"2d8+8d10+34","hd_value":10,"fort":11,"ref":1,"will":10,"save_mods":"Will: +1 vs. fear, +2 bonus vs. compulsion effects","defensive_abilities":["force of will (+2 vs. compulsion)"],"speed":[{"type":"land","speed":30}],"space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"5/day, DC 13, 1d6"},{"type":"hand of the acolyte","details":"6/day"},{"type":"smite chaos","details":"2/day, +2 attack and AC, +4 damage"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect chaos"}]},{"frequency":"5/day","spells":[{"spell":"discern lies"}]},{"frequency":"6/day","spells":[{"spell":"strength surge","details":"+2"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":2,"spellsprepared_concentration":5,"spellsprepared":[{"spell_level":1,"spell_slots":4,"spells":[{"spell":"cure light wounds","count":2},{"spell":"protection from chaos","type":"domain"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"create water"},{"spell":"detect magic"},{"spell":"light"},{"spell":"mending"}]}],"spelldomains":"Law, Magic","strength":14,"dexterity":8,"constitution":14,"intelligence":10,"wisdom":16,"charisma":14,"baseatk":9,"cmb":11,"cmb_special":"+15 sunder","cmd":20,"cmd_special":"22 vs. sunder","feats":[{"feat":"Alertness"},{"feat":"Greater Sunder"},{"feat":"Improved Critical (morningstar)"},{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (morningstar)"},{"feat":"Weapon Specialization (morningstar)"}],"skills":[{"skill":"Intimidate","value":15},{"skill":"Knowledge (history)","value":5},{"skill":"Knowledge (planes)","value":5},{"skill":"Perception","value":20},{"skill":"Sense Motive","value":14}],"languages":["Common"],"sq":["armor training 1","aura of law","discipline (pentamic faith: Strength)","Hellknight armor 1","Hellknight order (Order of the Godclaw)"],"special_abilities":[{"type":"Aura of Law","kind":"Ex","details":"The power of Lictor Ountor's aura of law is equal to that of a cleric of his total character level (10th level)."},{"type":"Detect Chaos","kind":"Sp","details":"This ability functions like a paladin's detect evil class feature, save that it detects chaos."},{"type":"Force of Will","kind":"Ex","details":"Lictor Ountor gains a+2 bonus on Will saves against spells with the compulsion descriptor."},{"type":"Hellknight Armor","kind":"Ex","details":"When Lictor Ountor wears Hellknight armor, he reduces its armor check penalty by 1, increases the maximum Dexterity bonus allowed by 1, and moves at full speed."},{"type":"Pentamic Faith","kind":"Ex","details":"This Hellknight discipline allows Lictor Ountor to gain the granted powers (but not domain spells) of the Strength domain as a 4th-level cleric."},{"type":"Smite Chaos","kind":"Su","details":"This ability functions as the paladin's smite evil class feature, but against chaotic-aligned creatures. This ability is twice as effective against outsiders with the chaotic subtype, chaotic-aligned aberrations, and fey."}],"during_combat":"Lictor Ountor is eager to get revenge on the Glorious Reclamation, but having been defeated once before, he fights with more caution against these foes, assuming he manages to get hold of replacement armor and weapons. He takes every opportunity he can to sunder the weapons of his enemies and is hesitant to use Power Attack unless he finds that he's hitting his foes each round without worry. He saves shield of faith for use against the most powerful foes, and when he does so, casts it on the first round of combat-assuming he can find an unholy symbol to use!","morale":"Lictor Ountor fights to the death, but if captured alive, bides his time as a prisoner for another chance at revenge.","source":"AP 107, Pathfinder Campaign Setting: The Inner Sea World Guide 278"},{"name":"Kazakador","cr":12,"xp":19200,"race":"dwarf","gender":"Male","age_category":"Adult","classes":[{"class":"inquisitor of Iomedae","level":13}],"alignment":"LG","size":"Medium","type":"humanoid","sub_types":["dwarf"],"init":4,"senses":["darkvision 60 ft."],"ac":33,"ac_touch":19,"ac_flat_footed":31,"ac_mods":"+8 armor, +4 deflection, +1 Dex, +1 dodge, +1 natural, +3 sacred, +5 shield","hp":114,"hd":"13d8+52","hd_value":13,"hp_mods":"fast healing 5","fort":12,"ref":7,"will":15,"save_mods":"+2 vs. poison, spells, and spell-like abilities","defensive_abilities":["defensive training","stalwart"],"speed":[{"type":"land","speed":20}],"melee":"+3 dwarven waraxe +19 (1d10+9/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"greater bane","details":"13 rounds/day"},{"type":"hatred"},{"type":"judgment","details":"5/day, 2 simultaneous"},{"type":"weapon master","details":"13 rounds/day"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect alignment"},{"spell":"discern lies","details":"13 rounds/day"}]},{"frequency":"6/day","spells":[{"spell":"battle rage","details":"+6"}]}],"spellsknown_caster":"inquisitor","spellsknown_caster_level":13,"spellsknown_concentration":16,"spellsknown":[{"spell_level":5,"spell_slots":1,"spells":[{"spell":"greater command"},{"spell":"righteous might"}]},{"spell_level":4,"spell_slots":3,"spells":[{"spell":"cure critical wounds"},{"spell":"divine power"},{"spell":"freedom of movement"},{"spell":"hold monster"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"cure serious wounds"},{"spell":"greater magic weapon"},{"spell":"heroism"},{"spell":"invisibility purge"},{"spell":"searing light"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"calm emotions"},{"spell":"confess"},{"spell":"cure moderate wounds"},{"spell":"spiritual weapon"},{"spell":"weapon of awe"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"cure light wounds"},{"spell":"detect evil"},{"spell":"divine favor"},{"spell":"ear-piercing scream"},{"spell":"shield of faith"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"brand"},{"spell":"detect magic"},{"spell":"disrupt undead"},{"spell":"guidance"},{"spell":"light"},{"spell":"read magic"}]}],"spelldomains":"War","strength":22,"dexterity":13,"constitution":14,"intelligence":10,"wisdom":16,"charisma":6,"baseatk":9,"cmb":15,"cmd":34,"cmd_special":"38 vs. bull rush, 38 vs. trip","feats":[{"feat":"Dodge"},{"feat":"Exotic Weapon Proficiency (dwarven waraxe)"},{"feat":"Iron Will"},{"feat":"Paired Opportunists"},{"feat":"Power Attack"},{"feat":"Precise Strike"},{"feat":"Shake It Off"},{"feat":"Shield Focus"},{"feat":"Shield Wall"},{"feat":"Toughness"},{"feat":"Weapon Focus (dwarven waraxe)"}],"skills":[{"skill":"Intimidate","value":20},{"skill":"Knowledge (arcana)","value":6},{"skill":"Knowledge (dungeoneering)","value":6},{"skill":"Knowledge (nature)","value":6},{"skill":"Knowledge (planes)","value":6},{"skill":"Knowledge (religion)","value":6},{"skill":"Perception","value":19},{"skill":"Sense Motive","value":25},{"skill":"Spellcraft","value":16},{"skill":"Stealth","value":11}],"languages":["Common","Dwarven"],"sq":["monster lore +3","solo tactics","stern gaze +6","track +6"],"gear":"+2 breastplate, +2 heavy steel shield, +1 dwarven waraxe, amulet of natural armor +1, belt of giant strength +4, cloak of resistance +2, skeleton key for most doors in Citadel Dinyar, keys to the guardroom and stockades (areas A6-A8), 150 gp","before_combat":"Kazakador casts greater magic weapon on his dwarven waraxe every day. Before combat, he casts freedom of movement and shield of faith on himself. Every morning, Knight Commander Graxus Phand casts status on Kazakador.","during_combat":"Kazakador typically uses his judgment class ability to gain judgments of sacred healing and sacred protection-his statistics reflect these bonuses. For the first few rounds of combat, he remains at range and casts spells, starting with a greater command to \"drop\" and following that with searing light or spiritual weapon. He prefers to bolster himself with both divine power and righteous might before entering melee if possible; if forewarned about the prospect of a fight (such as by hearing combat in area A22), he instead casts these two spells and abandons other spells in combat, immediately moving to attack in melee. Note that as soon as Kazakador takes damage or suffers an ailment, the status effect alerts Knight Commander Graxus Phand, who drops everything to come to area A23 to provide aid (assume that Graxus can arrive in this room 4 minutes after the first alert during the day or in 1 minute during the evening-this includes the time he takes to cast short-duration defensive spells such as bull's strength).","morale":"Kazakador fights to the death.","source":"AP 107, Pathfinder RPG Advanced Player's Guide 38"},{"name":"Jelena Asteren","cr":10,"xp":9600,"race":"human","gender":"Female","age_category":"middle age","classes":[{"class":"ex-paladin","level":11}],"alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human"],"init":5,"ac":26,"ac_touch":11,"ac_flat_footed":25,"ac_mods":"+11 armor, +1 Dex, +4 shield","hp":98,"hd":"11d10+33","hd_value":11,"fort":8,"ref":4,"will":6,"immunities":["charm","disease","fear"],"speed":[{"type":"land","speed":20}],"melee":"mwk longsword +15 (1d8+2/17-20)","ranged":"mwk composite longbow +13 (1d8+2/x3)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":12,"constitution":12,"intelligence":11,"wisdom":9,"charisma":18,"baseatk":11,"cmb":13,"cmb_special":"+15 bull rush","cmd":24,"cmd_special":"26 vs. bull rush","feats":[{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (longsword)"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Shield Focus"},{"feat":"Toughness"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Diplomacy","value":18},{"skill":"Knowledge (nobility)","value":9},{"skill":"Knowledge (religion)","value":8},{"skill":"Perception","value":10}],"languages":["Common"],"sq":["divine bond (weapon +3, 2/day)","mercies (fatigued, nauseated, sickened)"],"gear":"+2 full plate, +1 heavy steel shield, mwk composite longbow (+2 Str) with 20 arrows, mwk longsword, 32 gp, horn of goodness/evil","during_combat":"Jelena prefers to avoid combat if possible, but not just because she's always considered violence to be a tactic of last choice. She's managed for the past several weeks to hide the fact that she's lost her faith in hopes of finding it again (and thus regaining her powers) before having to admit the shame to her fellow knights, and avoiding combat is an important part of that deception. If forced to do so, she fights defensively and attempts to retreat to the closest area she suspects has allies-with whom she fights, focusing on flanking foes.","morale":"Jelena fights to the death, afraid that surrender or flight would only further damn her soul in the afterlife.","source":"AP 107"},{"name":"The Fist Of Iomedae","cr":13,"xp":25600,"race":"cloud giant","gender":"Female","age_category":"Adult","classes":[{"class":"monk","level":5}],"alignment":"LN","size":"Huge","type":"humanoid","sub_types":["giant"],"init":4,"senses":["low-light vision","scent"],"ac":32,"ac_touch":19,"ac_flat_footed":27,"ac_mods":"+4 Dex, +1 dodge, +1 monk, +13 natural, -2 size, +5 Wis","hp":204,"hd":"21d8+110","hd_value":21,"fort":22,"ref":16,"will":19,"save_mods":"+2 vs. enchantments","defensive_abilities":["evasion","rock catching"],"immunities":["disease"],"speed":[{"type":"land","speed":60}],"melee":"unarmed strike +27 (3d6+14/19-20) or unarmed strike flurry of blows +31 (3d6+14/19-20)","ranged":"rock +18 (2d6+21)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"flurry of blows"},{"type":"rock throwing","details":"140 feet"},{"type":"stunning fist","details":"9/day, DC 25"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"levitate","details":"000 lbs., self plus 2"},{"spell":"obscuring mist"}]},{"frequency":"1/day","spells":[{"spell":"fog cloud"}]}],"strength":38,"dexterity":18,"constitution":21,"intelligence":15,"wisdom":20,"charisma":12,"baseatk":15,"cmb":33,"cmb_special":"+35 bull rush, +35 overrun","cmd":52,"cmd_special":"54 vs. bull rush, 54 vs. overrun","feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Great Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (unarmed strike)"},{"feat":"Improved Overrun"},{"feat":"Improved Unarmed Strike"},{"feat":"Intimidating Prowess"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Staggering Critical"},{"feat":"Stunning Fist"}],"skills":[{"skill":"Acrobatics","value":22},{"skill":"Climb","value":23},{"skill":"Craft (stonemasonry)","value":9},{"skill":"Diplomacy","value":9},{"skill":"Intimidate","value":28},{"skill":"Knowledge (religion)","value":13},{"skill":"Perception","value":25},{"skill":"Perform (string instruments)","value":11},{"skill":"Sense Motive","value":25}],"languages":["Common","Celestial","Giant"],"sq":["fast movement","high jump","ki pool (7 points magic)","maneuver training","oversized weapon","slow fall 20 ft."],"gear":"amulet of natural armor +1, cloak of resistance +3, winged boots","before_combat":"The Fist activates her winged boots before combat if she can. Knight Commander Graxus Phand maintains a status effect on the Fist as well.","during_combat":"Numerous rocks lie around the cloister should the Fist need ammunition to throw, but she greatly prefers to use her fists in combat. She often utilizes Stunning Fist, and makes use of Improved Overrun to get through opponents and block progress into the main cathedral. Note that as soon as the Fist takes damage or suffers an ailment, the status effect alerts Knight Commander Graxus Phand, who drops everything to come to area A36 to provide aid (assume that Phand can arrive in this room 1d4+4 rounds after the first alert during the day or in 4 minutes during the evening-this includes the time he takes to cast short-duration defensive spells such as bull's strength).","morale":"The Fist fights to the death, but doesn't pursue foes out of Bastion Devotio.","source":"AP 107, Pathfinder RPG Bestiary 147"},{"name":"The Tears Of St. Ilnea","cr":14,"xp":38400,"race":"water elemental","age_category":"elder","alignment":"LG","size":"Huge","type":"outsider","sub_types":["elemental","extraplanar","native","water"],"templates_applied":"half-celestial","init":8,"senses":["darkvision 60 ft."],"ac":31,"ac_touch":21,"ac_flat_footed":22,"ac_mods":"+4 deflection, +8 Dex, +1 dodge, +10 natural, -2 size","hp":200,"hd":"16d10+112","hd_value":16,"fort":20,"ref":22,"will":10,"dr":"10/-","immunities":["disease","elemental traits"],"resists":["acid 10","cold 10","electricity 10"],"sr":25,"speed":[{"type":"fly","speed":40,"maneuverability":"good"},{"type":"land","speed":20},{"type":"swim","speed":90}],"melee":"2 slams +26 (4d8+12/19-20)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"drench"},{"type":"smite evil","details":"1/day, +1 attack and AC, +16 damage"},{"type":"vortex","details":"DC 30"},{"type":"water mastery"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"aid"},{"spell":"bless"},{"spell":"cure serious wounds"},{"spell":"detect evil"},{"spell":"dispel evil"},{"spell":"hallow"},{"spell":"holy word"},{"spell":"mass charm monster"},{"spell":"neutralize poison"},{"spell":"quickened holy smite"},{"spell":"remove disease"}]},{"frequency":"3/day","spells":[{"spell":"holy aura"},{"spell":"protection from evil"}]}],"strength":34,"dexterity":26,"constitution":23,"intelligence":12,"wisdom":13,"charisma":13,"baseatk":16,"cmb":30,"cmb_special":"+32 bull rush","cmd":53,"cmd_special":"55 vs. bull rush","feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (slam)"},{"feat":"Improved Natural Attack (slam)"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (holy smite)"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":27},{"skill":"Escape Artist","value":27},{"skill":"Fly","value":8},{"skill":"Knowledge (planes)","value":20},{"skill":"Perception","value":20},{"skill":"Sense Motive","value":20},{"skill":"Stealth","value":19},{"skill":"Swim","value":39}],"languages":["Aquan","Celestial"],"during_combat":"The Tears uses detect evil at the start of anything that looks like combat to ensure that those it faces are evil, but if it's attacked, it fights back, starting  with holy word (a much swifter method of determining which foes are evil). The Tears then casts holy aura and quickened holy smite, then moves to attack foes in melee. The elemental doesn't pursue foes more than 30 ft. from the pool's outer edges.","morale":"The Tears of St. Ilnea fights to the death.","source":"AP 107, Pathfinder RPG Bestiary 169, 127"},{"name":"Sevestra Hanail","cr":12,"xp":19200,"race":"human","gender":"Female","age_category":"Old","classes":[{"class":"cavalier","level":14,"archetype":"beast rider"}],"alignment":"LG","size":"Medium","type":"humanoid","sub_types":["good","human","lawful"],"templates_applied":"divine guardian","init":4,"senses":["darkvision 60 ft.","low-light vision"],"ac":22,"ac_touch":10,"ac_flat_footed":22,"ac_mods":"+12 armor","hp":151,"hd":"14d10+70","hd_value":14,"hp_mods":"fast healing 5","fort":14,"ref":4,"will":8,"defensive_abilities":["ability healing"],"immunities":["disease","mind-affecting effects","poison"],"speed":[{"type":"land","speed":50}],"melee":"+1 holy glaive +19 (1d10+2/19-20/x3 plus 2d6 vs. evil) or mwk longsword +18 (1d8+1/19-20)","ranged":"mwk composite longbow +15 (1d8+1/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"banner +3"},{"type":"cavalier's charge"},{"type":"challenge","details":"5/day, +14 damage"},{"type":"demanding challenge"},{"type":"greater banner"},{"type":"greater tactician","details":"3/day, Coordinated Maneuvers or Outflank, swift action, 10 rounds"},{"type":"mighty charge"}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"dimension door","details":"within sacred site only"}]},{"frequency":"1/day","spells":[{"spell":"arcane lock"},{"spell":"augury"},{"spell":"clairaudience/clairvoyance"},{"spell":"commune"},{"spell":"dismissal"},{"spell":"forbiddance"},{"spell":"guards and wards"},{"spell":"hold portal"}]},{"frequency":"3/day","spells":[{"spell":"alarm"},{"spell":"knock"}]}],"strength":13,"dexterity":10,"constitution":17,"intelligence":12,"wisdom":18,"charisma":14,"baseatk":14,"cmb":17,"cmd":25,"feats":[{"feat":"Coordinated Maneuvers"},{"feat":"Great Fortitude"},{"feat":"Heavy Armor Proficiency"},{"feat":"Improved Critical (glaive)"},{"feat":"Mounted Archery"},{"feat":"Mounted Combat"},{"feat":"Outflank"},{"feat":"Power Attack"},{"feat":"Ride-by Attack"},{"feat":"Spirited Charge"},{"feat":"Toughness"},{"feat":"Weapon Focus (glaive)"}],"skills":[{"skill":"Bluff","value":19,"special":"+7 to conceal information about sworn charge"},{"skill":"Handle Animal","value":19},{"skill":"Intimidate","value":19},{"skill":"Knowledge (religion)","value":13},{"skill":"Linguistics","value":6},{"skill":"Perception","value":23},{"skill":"Ride","value":12},{"skill":"Sense Motive","value":9}],"languages":["Common","Aquan","Celestial"],"sq":["blessed life","divine swiftness","exotic mount (lion named Silvermane)","I shall not be moved","keeper","order of the seal","sacred site"],"gear":"+3 full plate, +1 holy glaive, mwk composite  longbow (+3 Str) with 20 arrows, mwk longsword, belt of mighty constitution +2","during_combat":"Once battle begins, Sevestra uses her challenge ability on the most capable-looking melee fighter. After 3 rounds or once she's reduced to fewer than 80 hit points, a shield archon (if one still lives) uses its transpose ally ability to swap places with her, at which point she calls her mount Silvermane to her side to mount up. She prefers to fight with her glaive, maintaining reach as she can.","morale":"Sevestra fights until she is reduced below 20 hit points, at which time she casts dimension door, teleporting to area B7 with Silvermane, where she defends the fountain to her death.","source":"AP 107, Pathfinder RPG Bestiary 4 60, Pathfinder RPG Advanced Player's Guide 32, Pathfinder RPG Ultimate Combat 36"},{"name":"Silvermane","xp":0,"race":"lion mount","gender":"Male","age_category":"Adult","alignment":"LG","size":"Large","type":"animal","init":4,"senses":["low-light vision","scent"],"ac":30,"ac_touch":13,"ac_flat_footed":26,"ac_mods":"+6 armor, +3 Dex, +1 dodge, +11 natural, -1 size","hp":114,"hd":"12d8+60","hd_value":12,"fort":12,"ref":12,"will":8,"save_mods":"Will: +4 vs. enchantment spells and effects","defensive_abilities":["evasion"],"speed":[{"type":"land","speed":30}],"melee":"bite +16 (1d8+8 plus grab), 2 claws +16 (1d8+8)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"},{"type":"rake","details":"2 claws +16, 1d8+8"}],"strength":26,"dexterity":19,"constitution":18,"intelligence":2,"wisdom":15,"charisma":10,"baseatk":9,"cmb":18,"cmb_special":"+22 grapple","cmd":33,"cmd_special":"37 vs. trip","feats":[{"feat":"Dodge"},{"feat":"Endurance"},{"feat":"Improved Natural Attack (claw)"},{"feat":"Iron Will"},{"feat":"Medium Armor Proficiency"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":15}],"sq":["combat riding","devotion","multiattack","tricks(Attack, Combat Riding, Come, Defend, Down, Guard, Heel)"],"gear":"mwk breastplate barding","during_combat":"Silvermane defends Sevestra to the best of his ability, but left to his own devices, he focuses his attacks on the largest (or most heavily armored) foe.","morale":"Silvermane fights to the death.","source":"AP 107"},{"name":"Jelbi","cr":10,"xp":9600,"race":"gnome","gender":"Female","age_category":"Adult","classes":[{"class":"bard","level":11}],"alignment":"CG","size":"Small","type":"humanoid","sub_types":["gnome"],"init":2,"senses":["low-light vision"],"ac":23,"ac_touch":14,"ac_flat_footed":20,"ac_mods":"+6 armor, +2 Dex, +1 dodge, +3 shield, +1 size","hp":122,"hd":"11d8+55","hd_value":11,"fort":6,"ref":9,"will":9,"save_mods":"+2 vs. illusions, +4 vs. bardic   performance, language-dependent, and sonic, +4 vs. poison and fear","defensive_abilities":["defensive training"],"speed":[{"type":"land","speed":20}],"melee":"mwk longsword +10 (1d6-1/19-20)","ranged":"+1 composite shortbow +11 (1d4/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 28 rounds/day","details":"move action; countersong, dirge of doom, distraction, fascinate [DC 19], inspire competence +4, inspire courage +3, inspire greatness, suggestion [DC 19]"},{"type":"hatred"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"dancing lights"},{"spell":"ghost sound"},{"spell":"prestidigitation"},{"spell":"speak with animals"}]}],"spellsknown_caster":"bard","spellsknown_caster_level":11,"spellsknown_concentration":15,"spellsknown":[{"spell_level":4,"spell_slots":3,"spells":[{"spell":"dimension door"},{"spell":"dominate person"},{"spell":"greater invisibility"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"dispel magic"},{"spell":"haste"},{"spell":"purging finale"},{"spell":"slow"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"cure moderate wounds"},{"spell":"glitterdust"},{"spell":"hold person"},{"spell":"mirror image"},{"spell":"suggestion"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"charm person"},{"spell":"cure light wounds"},{"spell":"grease"},{"spell":"hideous laughter"},{"spell":"saving finale"},{"spell":"vanish"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"lullaby"},{"spell":"open/close"},{"spell":"prestidigitation"},{"spell":"read magic"},{"spell":"summon instrument"}]}],"strength":8,"dexterity":14,"constitution":16,"intelligence":12,"wisdom":8,"charisma":18,"baseatk":8,"cmb":7,"cmd":19,"feats":[{"feat":"Arcane Strike"},{"feat":"Craft Wand"},{"feat":"Dodge"},{"feat":"Extra Performance"},{"feat":"Iron Will"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":18},{"skill":"Craft (musical instruments)","value":15},{"skill":"Knowledge (geography)","value":13},{"skill":"Knowledge (history)","value":13},{"skill":"Knowledge (local)","value":16},{"skill":"Knowledge (nature)","value":14},{"skill":"Linguistics","value":6},{"skill":"Perception","value":15},{"skill":"Perform (dance)","value":18},{"skill":"Perform (string instruments)","value":18},{"skill":"Perform (wind instruments)","value":18}],"languages":["Common","Elven","Gnome","Infernal","Sylvan","Varisian"],"sq":["bardic knowledge +5","gnome magic","jack-of-all-trades","lore master 2/day","versatile performances (dance, string, wind)"],"gear":"+2 chain shirt, +2 buckler, +1 composite shortbow with 20 arrows, mwk longsword, satchel containing menus from 54 different Inner Sea taverns, 140 gp, wand of break enchantment (4 charges), wand of confusion (CL 10th, 15 charges), wand of cure serious wounds (8 charges)","before_combat":"Jelbi's statistics above include the effects of Nedowyn's heroes' feast.","during_combat":"Jelbi starts an audible bardic performance to inspire courage in herself and allies and casts greater invisibility. She casts haste as early in the combat as she can to affect all of the Fearless Crows, then moves on to use her offensive spells against opponents. If her greater invisibility ends, Jelbi casts it again unless she's out of 4th-level spell slots, in which case she casts mirror image instead. In melee combat, she always uses Arcane Strike, but she's ready to cast purging finale to get allies back in a fight or saving finale if an ally fails an important saving throw, restarting her inspire courage bardic performance on her next action.","morale":"Jelbi fights to the death unless she's the last one standing, in which case she flees Barleybridge.","source":"AP 107"},{"name":"Koss","cr":10,"xp":9600,"race":"azata-blooded aasimar","gender":"Male","age_category":"Adult","classes":[{"class":"sorcerer","level":11}],"alignment":"CG","size":"Medium","type":"outsider","sub_types":["native"],"init":3,"senses":["darkvision 60 ft."],"ac":23,"ac_touch":15,"ac_flat_footed":19,"ac_mods":"+4 armor, +1 deflection, +3 Dex, +1 dodge, +4 shield","hp":89,"hd":"11d6+34","hd_value":11,"fort":7,"ref":8,"will":11,"save_mods":"+4 vs. poison and fear","resists":["acid 10","cold 10","electricity 5"],"speed":[{"type":"fly","speed":40,"maneuverability":"good"},{"type":"land","speed":30}],"melee":"quarterstaff +5 (1d6-1)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"glitterdust"}]},{"frequency":"7/day","spells":[{"spell":"heavenly fire","details":"1d4+5 divine energy"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":11,"spellsknown_concentration":15,"spellsknown":[{"spell_level":5,"spell_slots":4,"spells":[{"spell":"flame strike"},{"spell":"overland flight"},{"spell":"wall of force"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"charm monster"},{"spell":"dimension door"},{"spell":"phantasmal killer"},{"spell":"remove curse"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"dispel magic"},{"spell":"lightning bolt"},{"spell":"magic circle against evil"},{"spell":"spiked pit"},{"spell":"vampiric touch"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"acid arrow"},{"spell":"blindness/deafness"},{"spell":"create pit"},{"spell":"glitterdust"},{"spell":"mirror image"},{"spell":"resist energy"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"bless"},{"spell":"feather fall"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"reduce person"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"disrupt undead"},{"spell":"ghost sound"},{"spell":"mending"},{"spell":"message"},{"spell":"ray of frost"},{"spell":"read magic"}]}],"bloodline":"celestial","strength":8,"dexterity":16,"constitution":14,"intelligence":10,"wisdom":12,"charisma":18,"baseatk":5,"cmb":5,"cmd":25,"feats":[{"feat":"Combat Casting"},{"feat":"Craft Staff"},{"feat":"Defensive Combat Training"},{"feat":"Dodge"},{"feat":"Empower Spell"},{"feat":"Eschew Materials"},{"feat":"Quicken Spell"},{"feat":"Toughness"}],"skills":[{"skill":"Diplomacy","value":6},{"skill":"Fly","value":21},{"skill":"Knowledge (arcana)","value":14},{"skill":"Spellcraft","value":14}],"languages":["Common","Celestial"],"sq":["bloodline arcana (summoned creatures gain DR 5/evil)","wings of heaven (11 minutes/day)"],"special_abilities":[{"type":"Azata-Blooded","details":"Descended from azatas, azata-blooded aasimars receive a +2 racial bonus to their Charisma and Wisdom scores, a +2 racial bonus on Diplomacy and Perform checks, and can use glitterdust once per day as a spell-like ability. These abilities replace the normal aasimar racial traits."}],"gear":"quarterstaff, cloak of resistance +2, ring of protection +1, potion of cure moderate wounds (2), staff of fire (6 charges)","before_combat":"Koss's statistics above include the effects of Nedowyn's heroes' feast. In addition, he casts mage armor, shield, and overland flight before getting into a fight.","during_combat":"Koss avoids melee combat, and tries to stay mobile in a fight so he can hit foes with his spells, preferring to use flight to remain out of melee reach but still in range to be affected  by allied spell effects. He casts mirror image on the first round of combat, then focuses on battlefield control for the following few rounds, using wall of force, spiked pit, and create pit to complicate things for the enemy. He's quick to use dispel magic on particularly dangerous effects as they come up, and relies on blindness/deafness when faced with foes who utilize sneak attacks or ranged attacks. If an ally is in deadly peril, Koss swoops in to teleport that ally and himself to safety with dimension door, but he won't travel too far if that means abandoning other Fearless Crows. He prefers to save area effect damage spells and his staff of fire to use against grouped foes once his allies have softened them up.","morale":"Koss fights to the death unless he's the last one standing, in which case he flees Barleybridge.","source":"AP 107, Pathfinder Player Companion: Blood of Angels 22, Pathfinder RPG Bestiary 7"},{"name":"Nedowyn","cr":10,"xp":9600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"cleric of Cayden Cailean","level":11}],"alignment":"CG","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":23,"ac_touch":12,"ac_flat_footed":21,"ac_mods":"+8 armor, +2 Dex, +3 shield","hp":122,"hd":"11d8+69","hd_value":11,"fort":10,"ref":5,"will":12,"save_mods":"+4 vs. poison and fear","speed":[{"type":"land","speed":40}],"melee":"+2 rapier +14 (1d6+2/18-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel positive energy","details":"7/day, DC 17, 6d6"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"charming smile","details":"11 rounds/day"},{"spell":"dimensional hop","details":"110 feet/day"}]},{"frequency":"7/day","spells":[{"spell":"dazing touch"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":11,"spellsprepared_concentration":15,"spellsprepared":[{"spell_level":6,"spell_slots":2,"spells":[{"spell":"find the path","type":"domain"},{"spell":"heroes' feast"}]},{"spell_level":5,"spell_slots":3,"spells":[{"spell":"breath of life"},{"spell":"charm monster","type":"domain"},{"spell":"wall of stone"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"chaos hammer"},{"spell":"dimension door","type":"domain"},{"spell":"divine power"},{"spell":"greater magic weapon"},{"spell":"holy smite"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"invisibility purge"},{"spell":"magic vestment"},{"spell":"prayer"},{"spell":"remove curse"},{"spell":"searing light"},{"spell":"suggestion","type":"domain"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"aid"},{"spell":"calm emotions","type":"domain"},{"spell":"hold person"},{"spell":"lesser restoration"},{"spell":"remove paralysis"},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"charm person","type":"domain"},{"spell":"command"},{"spell":"divine favor"},{"spell":"protection from law"},{"spell":"sanctuary"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"create water"},{"spell":"detect magic"},{"spell":"mending"},{"spell":"stabilize"}]}],"spelldomains":"Charm, Travel","strength":10,"dexterity":14,"constitution":16,"intelligence":8,"wisdom":18,"charisma":14,"baseatk":8,"cmb":9,"cmd":20,"feats":[{"feat":"Craft Wondrous Item"},{"feat":"Extra Channel"},{"feat":"Quick Channel"},{"feat":"Selective Channeling"},{"feat":"Toughness"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (rapier)"}],"skills":[{"skill":"Knowledge (religion)","value":13},{"skill":"Spellcraft","value":13}],"languages":["Common"],"sq":["agile feet (7/day)"],"gear":"mithral breastplate, +2 buckler, mwk rapier, belt of physical might (Dex, Con) +2, golden holy symbol of Cayden Cailean (worth 250 gp), scroll of air walk, scroll of heal","before_combat":"Nedowyn casts heroes' feast for the Fearless Crows in the morning, and its effects are included in his statistics above. In addition, he casts greater magic weapon on his rapier and magic vestment on his armor early every morning.","during_combat":"Nedowyn begins a combat by casting shield of faith, then joins Tanti in melee to support her. He relies primarily on channeled energy to keep the group healed, often using his Quick Channel feat to activate the ability as a move action and then get a bit more healing in with a spell. He relies on magic for ranged attacks, and abandons melee to aid allies with recovery spells like remove paralysis or breath of life as needed, but knows his role as a frontline combat companion to Tanti is as important to the group's success, so that the other Crows can hold back and provide support.","morale":"Nedowyn fights to the death.","source":"AP 107"},{"name":"Tanti","cr":10,"xp":9600,"race":"Half-Elf","gender":"Female","age_category":"Adult","classes":[{"class":"rogue","level":3,"archetype":"knife master"},{"class":"swashbuckler","level":8}],"alignment":"CG","size":"Medium","type":"humanoid","sub_types":["elf","human"],"init":6,"senses":["low-light vision"],"ac":24,"ac_touch":20,"ac_flat_footed":17,"ac_mods":"+4 armor, +3 deflection, +4 Dex, +3 dodge","hp":131,"hd":"3d8+8d10+55","hd_value":11,"fort":8,"ref":14,"will":8,"save_mods":"+2 vs. enchantments, +4 vs. poison and fear","defensive_abilities":["blade sense","charmed life 4/day","evasion","nimble +2"],"immunities":["sleep"],"speed":[{"type":"land","speed":30}],"melee":"+1 shock kukri +18 (1d4+16/15-20 plus 1d6 electricity)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"deeds","details":"derring-do, dodging panache, kip-up, menacing swordplay, opportune parry and riposte, precise strike, superior feint, swashbuckler initiative, swashbuckler's grace, targeted strike"},{"type":"panache","details":"5"},{"type":"sneak stab","details":"+2d8"},{"type":"swashbuckler weapon training +1"}],"strength":10,"dexterity":18,"constitution":18,"intelligence":8,"wisdom":12,"charisma":16,"baseatk":10,"cmb":11,"cmd":30,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Extra Panache"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Skill Focus (Acrobatics)"},{"feat":"Slashing Grace"},{"feat":"Spring Attack"},{"feat":"Weapon Focus (kukri)"},{"feat":"Weapon Specialization (kukri)"}],"skills":[{"skill":"Acrobatics","value":24},{"skill":"Bluff","value":17},{"skill":"Perception","value":13},{"skill":"Sleight of Hand","value":17},{"skill":"Stealth","value":13}],"languages":["Common","Elven"],"sq":["elf blood","hidden blade","rogue talent (combat trick)","swashbuckler finesse"],"gear":"+1 studded leather, +1 shock kukri, belt of incredible dexterity +2, cloak of resistance +1, 67 gp, potion of bear's endurance (3), potion of shield of faith +3 (3)","before_combat":"Tanti's stats include the effects of Nedowyn's heroes' feast. She drinks a potion of shield of faith and a potion of bear's endurance before entering a fight.","during_combat":"Tanti's fighting style is somewhat complex but rather effective. Working with allies (usually Nedowyn), she rarely, if ever, stands still long enough to make a full attack. Instead, she circles her enemies to line up flanking opportunities, but simultaneously seeks to provoke attacks of opportunity from foes so she can use opportune parry and riposte to try to get additional attacks on them instead as they attack her. If such movement puts her in a disadvantageous position when she flanks a foe, she uses Spring Attack to move out of danger after delivering the strike. By using up a foe's attacks of opportunity and parrying them, she prevents the opponent from using those attacks against spellcasting allies. She avoids spending her last point of panache if possible to maintain the benefits of her precise strike.","morale":"Tanti fights to the death unless she's the last one standing, in which case she flees Barleybridge.","source":"AP 107, Pathfinder RPG Ultimate Combat 72, Pathfinder RPG Advanced Class Guide 56"},{"name":"Order Of The Glyph Hellknight","cr":9,"xp":6400,"race":"human","age_category":"Adult","classes":[{"class":"fighter","level":7},{"class":"Hellknight","level":3}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":4,"ac":27,"ac_touch":10,"ac_flat_footed":27,"ac_mods":"+11 armor, +6 shield","hp":97,"hd":"10d10+37","hd_value":10,"fort":9,"ref":3,"will":6,"save_mods":"+4 vs. glyphs of warding and symbol spells, Will: +2 vs. fear and phantasms","defensive_abilities":["force of will (+2 vs. phantasm)"],"speed":[{"type":"land","speed":30}],"melee":"+1 battleaxe +15 (1d8+8/19-20/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"smite chaos","details":"1/day, +3 damage"},{"type":"weapon training","details":"axes +1"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":2,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect chaos"}]},{"frequency":"1/day","spells":[{"spell":"glyph of warding"}]},{"frequency":"2/day","spells":[{"spell":"discern lies"}]}],"strength":18,"dexterity":10,"constitution":14,"intelligence":13,"wisdom":13,"charisma":8,"baseatk":10,"cmb":14,"cmb_special":"+16 sunder","cmd":24,"cmd_special":"26 vs. sunder","feats":[{"feat":"Improved Critical (battleaxe)"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Shield Focus"},{"feat":"Toughness"},{"feat":"Weapon Focus (battleaxe)"},{"feat":"Weapon Specialization (battleaxe)"}],"skills":[{"skill":"Intimidate","value":10},{"skill":"Knowledge (history)","value":11},{"skill":"Knowledge (planes)","value":7},{"skill":"Linguistics","value":7},{"skill":"Perception","value":14}],"languages":["Common","Aklo","Azlanti","Draconic","Dwarven","Elven","Infernal","Jistka"],"sq":["armor training 2","aura of law","discipline (invoke glyph [see sidebar on page XX])","Hellknight armor 1","Hellknight order (Order of the Glyph)"],"special_abilities":[{"type":"Aura of Law","kind":"Ex","details":"The power of a Hellknight's aura of law is equal to that of a cleric of his total character level (10th level)."},{"type":"Detect Chaos","kind":"Sp","details":"This ability functions like a paladin's detect evil class feature, save that it detects chaos."},{"type":"Force of Will","kind":"Ex","details":"The Hellknight gains a +2 bonus on Will saves against spells with the phantasm descriptor."},{"type":"Hellknight Armor","kind":"Ex","details":"The Hellknight reduces the armor check penalty of Hellknight armor by 1, increases the maximum Dexterity bonus allowed by 1, and moves at full speed."},{"type":"Smite Chaos","kind":"Su","details":"This ability functions as the paladin's smite evil class feature, but against chaotic-aligned creatures. This ability is twice as effective against outsiders with the chaotic subtype, chaotic-aligned aberrations, and fey."}],"gear":"+2 Hellknight plate, +1 tower shield, +1 battleaxe","during_combat":"Order of the Glyph Hellknights favor the use of Power Attack in combat; faced with foes who seem to be dependent on weapons, they won't hesitate to take advantage of Improved Sunder as well.","morale":"Order of the Glyph Hellknights fight to the death.","source":"AP 107, Pathfinder Campaign Setting: The Inner Sea World Guide 278"}];
